mapper.select:
SELECT subject_code, subject_name, subject_level, parent_code, direction, qc_amount, period_debit, period_credit, qm_amount FROM t_kmye WHERE org_id = #{orgId} AND kjyear_month = #{kjyearMonth}
AND (subject_code LIKE CONCAT(#{subjectCode}, '%') OR subject_name LIKE CONCAT('%', #{subjectCode}, '%'))
ORDER BY subject_code

SELECT project_code, project_name, balance, credit_period, credit_line, aging_type, kjyear_month, not_due1_to30_days, not_due31_to90_days, not_due91_to180_days, not_due181_days, due1_to30_days, due31_to90_days, due91_to180_days, due181_to360_days, due361_to720_days, due721_to1080_days, due1081_to1440_days, due1441_days, due_today FROM t_age_analysis WHERE org_id = #{orgId} AND kjyear_month = #{kjyearMonth} AND aging_type = #{agingType}
AND (project_code LIKE CONCAT('%', #{projectCode}, '%') OR project_name LIKE CONCAT('%', #{projectCode}, '%'))
ORDER BY balance DESC
